Based on the project structure, I'll create the error boundary as a TypeScript component.

<function_calls>
<invoke name="Write">
<parameter name="file_path">/Users/user/src/components/ErrorBoundary.tsx</parameter>
<parameter name="content">import { Component, type ErrorInfo, type ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error("[ErrorBoundary] Caught error:", error);
    console.error("[ErrorBoundary] Component stack:", info.componentStack);
  }

  reset = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (!error) return children;

    if (fallback) return fallback(error, this.reset);

    return (
      <div role="alert" style={styles.container}>
        <h2 style={styles.title}>Something went wrong</h2>
        <pre style={styles.message}>{error.message}</pre>
        <button onClick={this.reset} style={styles.button}>
          Try again
        </button>
      </div>
    );
  }
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "center",
    padding: "2rem",
    gap: "1rem",
    fontFamily: "sans-serif",
  },
  title: {
    margin: 0,
    fontSize: "1.25rem",
    color: "#b91c1c",
  },
  message: {
    margin: 0,
    padding: "0.75rem 1rem",
    background: "#fef2f2",
    border: "1px solid #fecaca",
    borderRadius: "0.375rem",
    fontSize: "0.875rem",
    color: "#7f1d1d",
    maxWidth: "100%",
    overflowX: "auto",
    whiteSpace: "pre-wrap",
    wordBreak: "break-word",
  },
  button: {
    padding: "0.5rem 1.25rem",
    background: "#2563eb",
    color: "#fff",
    border: "none",
    borderRadius: "0.375rem",
    fontSize: "0.875rem",
    cursor: "pointer",
  },
};
</parameter>
